import json,gzip,base64
import numpy as np
from pathlib import Path
root=Path('C:/Users/andyb/Desktop')
d=json.loads(gzip.decompress(base64.b64decode((root/'meeting-data.b64').read_text())))
cfg=json.loads((root/'BSFM_ENVIRONMENTS/s10-hole-plots/configurations.json').read_text())
coord=np.load(root/'BSFM_ENVIRONMENTS/s10-hole-plots/coordinates.npz')
splits=np.load(root/'BSFM_ENVIRONMENTS/s10-hole-plots/split-indices.npz')
for r in d['configurations']:
    r['geometry']=next(x for x in cfg['configurations'] if x['id']==r['id'])
    for short,long in [('train','training'),('test','heldout')]:
        ix=splits[r['id']+'_'+long+'_full_indices']
        r[short+'_xy']=coord['slocs'][ix,::-1].round(6).tolist()
        r[short+'_type']=coord['cell_id'][ix].tolist()
template=r'''<!doctype html><html><head><meta charset="utf-8"><title>BSFM • S10 held-out prediction</title><style>
*{box-sizing:border-box}body{margin:0;background:#f1f4f7;color:#1d2939;font:15px system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:35px}h1{font-size:38px;letter-spacing:-1.5px;margin:8px 0}h2{margin:30px 0 10px}h3{margin:5px 0}.eyebrow{color:#087c82;font-weight:750;letter-spacing:2px}.sub{color:#526175;max-width:1050px;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card,.panel{background:white;border:1px solid #dbe3eb;border-radius:14px;padding:18px;box-shadow:0 3px 15px #23354b06}.card canvas{width:100%;height:260px}.label{font-size:12px;color:#57677b}.number{font-size:26px;font-weight:750}canvas{display:block;width:100%}.plots{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.plots canvas{height:360px}.controls{display:flex;gap:18px;align-items:center;flex-wrap:wrap;margin:18px 0}select{padding:10px;border:1px solid #abbcc9;border-radius:7px;max-width:500px;font-size:15px}.badge{background:#fff1d5;padding:10px 15px;border-radius:8px;color:#775115;margin:18px 0;line-height:1.5}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:12px;border-bottom:1px solid #e6ebef}.small{font-size:12px;color:#607083;line-height:1.7}.legend{display:flex;gap:20px;margin:10px 0}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}.bar{height:12px;background:linear-gradient(90deg,#292d76,#168eaf,#81d6aa,#ffe784);border-radius:5px}.errorbar{background:linear-gradient(90deg,#285fb6,#f8f9fa,#c73939)}.range{display:flex;justify-content:space-between;font-size:12px;color:#637387}.twocol{display:grid;grid-template-columns:1.5fr 1fr;gap:18px;margin-top:20px}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,1fr)}.plots,.twocol{grid-template-columns:1fr}}@media print{main{padding:10px}.card,.panel{break-inside:avoid}select{border:0}h1{font-size:28px}}
</style></head><body><main><div class="eyebrow">BSFM / MEETING SNAPSHOT</div><h1>What can the flat model predict inside a hole?</h1><p class="sub">S10 · 50% cell subset · 91 genes · 3 cell types · K = 12 · L14 / 784 finite features. Four circle configurations share the full-tissue mesh. Only cells outside the holes enter initialization and fitting.</p><div class="badge"><b>Preliminary flat-model results.</b> All completed production draws at the recorded snapshot are included; warmup and bridge sweeps are excluded. Early single-chain results, without convergence assessment. Full-sample SCTransform normalization was reused with approval. No deep-model comparison is available in this report.</div><h2>01 / The four held-out designs</h2><div id="legend" class="legend"></div><p class="small">Solid points: training cells colored by type. Pale points within outlined circles: omitted cells, also colored by type. The full 4,712-cell selected tissue is shown in each panel.</p><div id="cards" class="grid"></div><h2>02 / Held-out prediction performance</h2><p class="sub">For every saved iteration, condition the finite-feature factor fields on the training cells, then multiply by the saved cell-type loadings. Average those per-iteration conditional means to obtain the displayed posterior mean. Lower error is better.</p><div class="panel"><table><thead><tr><th>Configuration</th><th>Saved draws</th><th>Held-out cells</th><th>Flat RMSE</th><th>Flat MAE</th><th>Baseline RMSE</th><th>RMSE change</th></tr></thead><tbody id="metrics"></tbody></table><p class="small">Baseline: training cell-type mean for each gene. Scores pool all 91 genes and all omitted cells in each scenario. Different scenarios omit different cells and have different draw counts; comparisons are descriptive, not a controlled estimate of the effect of hole size.</p></div><h2>03 / Gene-level spatial predictions</h2><p class="sub">Expression panels show the same held-out cells and share the same color scale. Gray context points are training cells. Values are SCTransform expression, with training cell-type means added back to the centered model response.</p><div class="controls"><label>Scenario <select id="scenario"></select></label><label>Gene <select id="gene"></select></label></div><p id="selection" class="small"></p><div class="plots"><div class="panel"><h3>Observed expression</h3><canvas id="truth"></canvas><div class="bar"></div><div class="range scale"></div></div><div class="panel"><h3>Flat posterior mean</h3><canvas id="mean"></canvas><div class="bar"></div><div class="range scale"></div></div><div class="panel"><h3>Prediction − observation</h3><canvas id="error"></canvas><div class="bar errorbar"></div><div class="range" id="errorScale"></div></div></div><div class="twocol"><div class="panel"><h3>Held-out gene scores, all 91 genes</h3><p class="small">Sorted by observed held-out variance. Spatial panels use six explicitly selected exploratory genes: highest variance, largest error relative to baseline, and lowest error relative to baseline across scenarios. This selection uses held-out outcomes and is descriptive, not independent validation.</p><div style="max-height:400px;overflow:auto"><table><thead><tr><th>Gene</th><th>Flat RMSE</th><th>Baseline RMSE</th><th>Change</th></tr></thead><tbody id="geneTable"></tbody></table></div></div><div class="panel"><h3>Prediction versus observation</h3><canvas id="scatter" style="height:340px"></canvas><p id="geneStats" class="small"></p></div></div><h2>04 / Scope and provenance</h2><div class="panel small"><div id="provenance"></div><p>Predictions are conditional means, not noisy posterior predictive realizations. Metrics compare the posterior mean with the actual omitted-cell response; no predictive intervals or coverage claim is made. The original full mesh is preserved. All per-draw prediction arrays, source transaction identities and validation receipts are retained on HPC. Source sampler code is on the execution/review branch; this report does not promote it to accepted scientific main.</p><p>Interpretation: inspect both successful and poor predictions. These results can reveal flat-model behavior but cannot establish that a deep model performs better. No missing results are imputed.</p></div></main><script>const D=__DATA__;
const rows=D.configurations,cols=['#008d92','#d37b24','#8c60b7'],fmt=x=>Number(x).toFixed(3),title=r=>`${r.geometry.circles} circles · diameter ${r.geometry.diameter_fraction}`;
document.getElementById('legend').innerHTML=rows[0].cell_types.map((n,i)=>`<span><i class="dot" style="background:${cols[i]}"></i>${n}</span>`).join('');
function setup(id){let c=document.getElementById(id),w=c.clientWidth,h=c.clientHeight;c.width=w*2;c.height=h*2;let ctx=c.getContext('2d');ctx.scale(2,2);return [ctx,w,h]}
function spatial(id,r,vals,lim,error=false){let [ctx,w,h]=setup(id),all=r.train_xy.concat(r.test_xy),x0=Math.min(...all.map(p=>p[0])),x1=Math.max(...all.map(p=>p[0])),y0=Math.min(...all.map(p=>p[1])),y1=Math.max(...all.map(p=>p[1]));let s=Math.min((w-24)/(x1-x0),(h-24)/(y1-y0)),ox=(w-s*(x1-x0))/2,oy=(h-s*(y1-y0))/2;let xy=p=>[ox+(p[0]-x0)*s,h-oy-(p[1]-y0)*s];function point(p,c,rad,a=1){let [x,y]=xy(p);ctx.fillStyle=c;ctx.globalAlpha=a;ctx.beginPath();ctx.arc(x,y,rad,0,7);ctx.fill()};r.train_xy.forEach((p,i)=>point(p,vals?'#d9dfe5':cols[r.train_type[i]],vals?1.15:1.5));r.test_xy.forEach((p,i)=>point(p,vals?color(vals[i],lim,error):cols[r.test_type[i]],vals?2.8:1.7,vals?1:.24));ctx.globalAlpha=1;ctx.strokeStyle='#263d58';ctx.lineWidth=.9;r.geometry.centers_xy.forEach(p=>{let[x,y]=xy(p);ctx.beginPath();ctx.arc(x,y,r.geometry.radius*s,0,7);ctx.stroke()})}
function color(v,l,err){let t=Math.max(0,Math.min(1,(v-l[0])/(l[1]-l[0]||1)));let stops=err?[[40,95,182],[248,249,250],[199,57,57]]:[[41,45,118],[22,142,175],[129,214,170],[255,231,132]];let z=t*(stops.length-1),i=Math.min(stops.length-2,Math.floor(z)),a=z-i;return 'rgb('+stops[i].map((x,j)=>Math.round(x+(stops[i+1][j]-x)*a)).join(',')+')'}
document.getElementById('cards').innerHTML=rows.map((r,i)=>`<div class="card"><h3>${title(r)}</h3><div class="label">${r.training.toLocaleString()} training · ${r.heldout.toLocaleString()} held out</div><canvas id="map${i}"></canvas><span class="number">${r.draws}</span> <span class="label">completed production draws</span></div>`).join('');
document.getElementById('metrics').innerHTML=rows.map(r=>`<tr><td>${title(r)}</td><td>${r.draws}</td><td>${r.heldout}</td><td>${fmt(r.rmse)}</td><td>${fmt(r.mae)}</td><td>${fmt(r.baseline_rmse)}</td><td>${(100*(r.rmse/r.baseline_rmse-1)).toFixed(1)}%</td></tr>`).join('');
document.getElementById('scenario').innerHTML=rows.map((r,i)=>`<option value="${i}">${title(r)}</option>`).join('');document.getElementById('gene').innerHTML=D.selected.map(g=>`<option value="${g}">${rows[0].genes[g]} — ${D.reasons[g]}</option>`).join('');
function update(){let r=rows[+document.getElementById('scenario').value],g=+document.getElementById('gene').value,idx=D.selected.indexOf(g),t=r.truth[idx],m=r.mean[idx],e=m.map((v,i)=>v-t[i]),lim=[Math.min(...t,...m),Math.max(...t,...m)],el=Math.max(...e.map(Math.abs));spatial('truth',r,t,lim);spatial('mean',r,m,lim);spatial('error',r,e,[-el,el],true);document.querySelectorAll('.scale').forEach(x=>x.innerHTML=`<span>${fmt(lim[0])}</span><span>${fmt(lim[1])}</span>`);document.getElementById('errorScale').innerHTML=`<span>${fmt(-el)}</span><span>0</span><span>${fmt(el)}</span>`;document.getElementById('selection').textContent=`Exploratory selection: ${D.reasons[g]}. ${r.genes[g]} · ${r.heldout} omitted cells · ${r.draws} saved production draws.`;document.getElementById('geneTable').innerHTML=r.genes.map((n,i)=>i).sort((a,b)=>r.gene_variance[b]-r.gene_variance[a]).map(i=>`<tr><td>${r.genes[i]}</td><td>${fmt(r.gene_rmse[i])}</td><td>${fmt(r.gene_baseline_rmse[i])}</td><td>${(100*(r.gene_rmse[i]/r.gene_baseline_rmse[i]-1)).toFixed(1)}%</td></tr>`).join('');let [ctx,w,h]=setup('scatter'),pad=42,s=Math.min(w,h)-2*pad,map=v=>pad+(v-lim[0])/(lim[1]-lim[0]||1)*s;ctx.strokeStyle='#8997a7';ctx.beginPath();ctx.moveTo(pad,h-pad);ctx.lineTo(pad+s,h-pad-s);ctx.stroke();t.forEach((v,i)=>{ctx.fillStyle=cols[r.test_type[i]];ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(map(v),h-map(m[i]),2,0,7);ctx.fill()});ctx.globalAlpha=1;ctx.fillStyle='#4a5b6e';ctx.font='12px system-ui';ctx.fillText('Observed →',w/2-35,h-5);ctx.fillText('Predicted ↑',5,16);ctx.fillText(fmt(lim[0]),pad,h-pad+17);ctx.fillText(fmt(lim[1]),pad+s-25,h-pad+17);document.getElementById('geneStats').textContent=`${r.genes[g]} held-out RMSE: ${fmt(r.gene_rmse[g])}; baseline: ${fmt(r.gene_baseline_rmse[g])}. Diagonal indicates perfect prediction.`}
document.getElementById('provenance').textContent=`Snapshot: ${D.timestamp}. Prediction code commit: ${D.commit}. HPC: /work/abussing/bsfm-consolidation/evidence/meeting-flat-922a558. Maximum absolute fast-mean versus existing Cholesky check: ${Math.max(...rows.map(r=>r.validation_max_abs)).toExponential(3)} (all 12 factors of first draw per scenario).`;function draw(){rows.forEach((r,i)=>spatial('map'+i,r));update()}document.getElementById('scenario').onchange=update;document.getElementById('gene').onchange=update;window.onresize=draw;draw();</script></body></html>'''
(root/'BSFM-S10-Meeting.html').write_text(template.replace('__DATA__',json.dumps(d,separators=(',',':')).replace('</','<\\/')),encoding='utf-8')
print(root/'BSFM-S10-Meeting.html')
